"use client";

import { useState } from "react";

export default function LikeButton() {
  const [count, setCount] = useState(0);

  return (
    <button
      type="button"
      className="rounded-md border border-gray-300 px-4 py-2 text-base hover:bg-gray-100"
      onClick={() => setCount((current) => current + 1)}
    >
      Like ({count})
    </button>
  );
}

