import { expect, test } from "@playwright/test";

// Uncaught browser errors are collected for every test in this file.
let errors: string[];

test.beforeEach(async ({ page }) => {
  errors = [];
  page.on("pageerror", (err) => errors.push(err.message));
  await page.goto("/");
});

test.afterEach(() => {
  expect(errors).toEqual([]);
});

test("Home page shows a 'Like (0)' button when first opened", async ({ page }) => {
  await test.step("Open the home page", async () => {
    await expect(page.getByRole("heading", { level: 1 })).toHaveText("Hello from the starter app");
  });

  await test.step("Look at the Like button", async () => {
    await expect(page.getByRole("button", { name: "Like (0)" })).toBeVisible();
  });
});

test("One click on the Like button makes it read 'Like (1)'", async ({ page }) => {
  await test.step("Click the 'Like (0)' button once", async () => {
    await page.getByRole("button", { name: "Like (0)" }).click();
  });

  await test.step("The button reads 'Like (1)'", async () => {
    await expect(page.getByRole("button", { name: "Like (1)" })).toHaveText("Like (1)");
  });
});

test("Two clicks on the Like button make it read 'Like (2)'", async ({ page }) => {
  await test.step("Click the Like button", async () => {
    await page.getByRole("button", { name: "Like (0)" }).click();
  });

  await test.step("Click the Like button again", async () => {
    await page.getByRole("button", { name: "Like (1)" }).click();
  });

  await test.step("The button reads 'Like (2)'", async () => {
    await expect(page.getByRole("button", { name: "Like (2)" })).toHaveText("Like (2)");
  });
});

test("The Like count keeps rising on further clicks", async ({ page }) => {
  await test.step("Click the Like button three times", async () => {
    await page.getByRole("button", { name: "Like (0)" }).click();
    await page.getByRole("button", { name: "Like (1)" }).click();
    await page.getByRole("button", { name: "Like (2)" }).click();
  });

  await test.step("The button reads 'Like (3)'", async () => {
    await expect(page.getByRole("button", { name: "Like (3)" })).toHaveText("Like (3)");
  });
});

test("Reloading the page resets the count to 'Like (0)'", async ({ page }) => {
  await test.step("Click the Like button twice", async () => {
    await page.getByRole("button", { name: "Like (0)" }).click();
    await page.getByRole("button", { name: "Like (1)" }).click();
    await expect(page.getByRole("button", { name: "Like (2)" })).toHaveText("Like (2)");
  });

  await test.step("Reload the page", async () => {
    await page.reload();
  });

  await test.step("The button reads 'Like (0)' again", async () => {
    await expect(page.getByRole("button", { name: "Like (0)" })).toHaveText("Like (0)");
  });
});

test("The Like button still counts clicks after a reload", async ({ page }) => {
  await test.step("Click the Like button twice", async () => {
    await page.getByRole("button", { name: "Like (0)" }).click();
    await page.getByRole("button", { name: "Like (1)" }).click();
  });

  await test.step("Reload the page", async () => {
    await page.reload();
    await expect(page.getByRole("button", { name: "Like (0)" })).toHaveText("Like (0)");
